settings:
{
  "libraryTypes": {
    // System.Text.Json on for the queries of this folder alone, so that SQL Server 2025's json is JsonElement, where
    // the project's settings file leaves the library at its default, off.
    "json": "on",
  },
  "columnTypes": {
    // A class of the project on an nvarchar by the opt-in of a settings file, read and sent through the serializer.
    "json_values.settings_meta": { "type": "OrderMetadata", "json": true },
  },
}
{
  // The dialect of every query of the project.
  "dialect": "mssql",
  // The logical database that a query is described against, unless its file names another.
  "database": "app",
  // What a query generates: its method and its models, which need an entry in the sidecar beside its file.
  "output": "Methods",
  // The suffix of the model of a query's parameters.
  "inputModelSuffix": "Args",
  // The kind of type that a query's input model is.
  "inputModelType": "record",
  "typeOverrides": {
    // The C# type that date is read as, in place of the default of the type map.
    "date": "System.DateOnly",
  },
  // The collection type of a query's rows, where no marker or nearer settings file sets one.
  "collectionType": "IReadOnlyList",
}
{
  // The end of every search for settings files in this repository.  A settings file above the checkout, such as the
  // main checkout's when this is a worktree under .claude/worktrees/, would otherwise reach every project here that
  // has no root file of its own.
  "root": true,
}
